import numpy as np, sys
def read_xyz(path):
    with open(path) as f:
        lines = f.read().strip().split("\n")
    n = int(lines[0])
    els, xyz = [], []
    for l in lines[2:2+n]:
        parts = l.split()
        els.append(parts[0]); xyz.append([float(x) for x in parts[1:4]])
    return els, np.array(xyz)
cov = {"H":0.31,"C":0.76,"N":0.71,"O":0.66,"P":1.07,"Cl":1.02,"Ru":1.46}
els, pos = read_xyz(sys.argv[1])
n = len(els)
adj = [[] for _ in range(n)]
for i in range(n):
    for j in range(i+1,n):
        d = np.linalg.norm(pos[i]-pos[j])
        if d < cov[els[i]]+cov[els[j]]+0.45:
            adj[i].append(j); adj[j].append(i)
# BFS fragments
seen = [False]*n; frags = 0
for s in range(n):
    if seen[s]: continue
    frags += 1
    stack=[s]; seen[s]=True
    while stack:
        u=stack.pop()
        for v in adj[u]:
            if not seen[v]: seen[v]=True; stack.append(v)
print("fragments:", frags)
ru = els.index("Ru")
print("Ru neighbors:", [(els[v], v, round(np.linalg.norm(pos[v]-pos[ru]),2)) for v in adj[ru]])
# check H counts on carbene C (29) and benzylidene C (3)
for idx in (29,3):
    print(idx, els[idx], "neighbors:", [(els[v],v) for v in adj[idx]])
